'AC-reporting.balance-sheet.1'; from decimal import Decimal; import pytest; from src.reporting.base.balance_sheet_calculator import calculate_balance_sheet_equation, calculate_currency_translation_adjustment
def test_balanced_single_currency_evaluation(): totals = calculate_balance_sheet_equation(total_assets=Decimal('1000.00'), total_liabilities=Decimal('300.00'), total_equity=Decimal('500.00'), net_income=Decimal('200.00'), unrealized_fx=Decimal('0.00'), net_worth_adjustment=Decimal('0.00'), cta_adjustment=Decimal('0.00')); assert totals.is_balanced is True; assert totals.equation_delta == Decimal('0.00'); assert totals.total_assets == Decimal('1000.00'); assert totals.total_liabilities_and_equity == Decimal('1000.00'); _m1_totals = calculate_balance_sheet_equation(total_assets=Decimal('1000.00'), total_liabilities=Decimal('300.00'), total_equity=Decimal('500.00'), net_income=Decimal('150.00'), unrealized_fx=Decimal('0.00'), net_worth_adjustment=Decimal('0.00')); assert _m1_totals.is_balanced is False; assert _m1_totals.equation_delta == Decimal('50.00'); _m2_cta = calculate_currency_translation_adjustment(is_multicurrency=True, pnl_translation_variance=Decimal('9.78')); assert _m2_cta == Decimal('9.78'); _m2_totals = calculate_balance_sheet_equation(total_assets=Decimal('25737.69'), total_liabilities=Decimal('0.00'), total_equity=Decimal('10000.00'), net_income=Decimal('15727.91'), unrealized_fx=Decimal('0.00'), net_worth_adjustment=Decimal('0.00'), cta_adjustment=_m2_cta); assert _m2_totals.is_balanced is True; assert _m2_totals.equation_delta == Decimal('0.00'); assert _m2_totals.cta_adjustment == Decimal('9.78'); _m3_cta = calculate_currency_translation_adjustment(is_multicurrency=False, pnl_translation_variance=Decimal('100.00')); assert _m3_cta == Decimal('0.00')
async def test_reporting_domain_ports_protocols():
    from datetime import date; from uuid import uuid4; from src.ledger import AccountType; from src.reporting.base.ports import LedgerBalanceProvider, PortfolioAdjustmentProvider, ValuationLinesProvider
    class RealLedgerBalanceProvider:
        async def __call__(self, user_id, account_types, as_of_date, target_currency, *, fx_warnings=None, included_currencies=None): return {uuid4(): Decimal('100.00')}
    class RealValuationLinesProvider:
        async def __call__(self, user_id, *, as_of_date, target_currency, include_restricted=True, warnings=None): return ([{'name': 'Asset'}], [{'name': 'Liability'}])
    class RealPortfolioAdjustmentProvider:
        async def __call__(self, user_id, *, as_of_date, target_currency, asset_lines, warnings=None): return [{'name': 'Adjustment'}]
    ledger_provider = RealLedgerBalanceProvider(); val_provider = RealValuationLinesProvider(); port_provider = RealPortfolioAdjustmentProvider(); assert isinstance(ledger_provider, LedgerBalanceProvider); assert isinstance(val_provider, ValuationLinesProvider); assert isinstance(port_provider, PortfolioAdjustmentProvider); uid = uuid4(); d = date(2026, 1, 1); res_ledger = await ledger_provider(uid, (AccountType.ASSET,), d, 'SGD'); assert len(res_ledger) == 1; res_val = await val_provider(uid, as_of_date=d, target_currency='SGD'); assert len(res_val[0]) == 1; res_port = await port_provider(uid, as_of_date=d, target_currency='SGD', asset_lines=[]); assert len(res_port) == 1; assert await LedgerBalanceProvider.__call__(None, uid, (AccountType.ASSET,), d, 'SGD') is None; assert await ValuationLinesProvider.__call__(None, uid, as_of_date=d, target_currency='SGD') is None; assert await PortfolioAdjustmentProvider.__call__(None, uid, as_of_date=d, target_currency='SGD', asset_lines=[]) is None
